"""run_square, generated by PythFinder -- do not edit."""


def run(core):
    """Drive this run. The only thing runs.py needs to call."""
    # Team robot
    drive = core.configure(
        wheel_diameter=55.6, axle_track=160.1,
        straight_speed=200, straight_acceleration=400,
        turn_rate=150, turn_acceleration=300,
        use_gyro=True)
    core.set_heading(0)

    drive.straight(400)
    core.turn_to(90, 90)
    drive.straight(300)
    core.turn_to(180, 90)
    drive.straight(300)
    core.turn_to(270, 90)
    drive.straight(300)
    core.turn_to(0, 90)

    core.stopTaskMotors()
